(()=>{
 const open=document.getElementById('openAbout');if(!open)return;
 const about=document.createElement('dialog');about.className='workspace-dialog about-dialog';about.setAttribute('aria-label','About');
 about.innerHTML='<img class="about-mascot" src="./about-frog.png" alt="" aria-hidden="true" draggable="false"><button type="button" class="dialog-close" aria-label="Close About">×</button><p>Explore how NEAR Intents activity turns into fees, revenue and buybacks—and how that compares with token issuance.</p><p>Overview shows the recorded activity. Integrators shows the apps bringing swaps. Forecast lets you explore scenarios using your own assumptions.</p><div class="about-actions"><button type="button" id="openMethods">Data &amp; methods</button><a href="./methodology.md" download>Read the documentation ↗</a></div>';
 document.body.append(about);open.onclick=()=>about.showModal();about.querySelector('.dialog-close').onclick=()=>about.close();about.onclick=e=>{if(e.target===about)about.close()};
 const methods=document.createElement('dialog');methods.className='workspace-dialog methods-dialog';methods.setAttribute('aria-labelledby','methodsTitle');methods.innerHTML='<button type="button" class="dialog-close" aria-label="Close data and methods">×</button><h2 id="methodsTitle">Data &amp; methods</h2><p>Figures come from saved source records. Missing observations stay missing. Forecasts are scenarios, not promises.</p><p><a href="./methodology.md" download>Download the full methodology ↗</a></p>';
 document.querySelectorAll('.integrator-method,.research-method:not(#relationships)').forEach(e=>{e.open=false;methods.append(e)});
 const note=document.createElement('p');note.textContent='Whale activity follows a sample of wallets holding at least 100,000 NEAR when checked. It counts known exchange transfers and verified swaps, excluding ordinary wallet-to-wallet transfers. It is not a ranking of every holder.';methods.append(note);document.body.append(methods);
 document.getElementById('openMethods').onclick=()=>{about.close();methods.showModal()};methods.querySelector('.dialog-close').onclick=()=>methods.close();methods.onclick=e=>{if(e.target===methods)methods.close()};
})();
